package com.airesumebuilder.feature.subscription.service;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.airesumebuilder.common.exception.ValidationException;import com.airesumebuilder.feature.subscription.repository.SubscriptionRepository;import java.time.Instant;import org.junit.jupiter.api.Test;
class SubscriptionServiceTest{@Test void provisionsFreePlanWhenNoneExists(){SubscriptionRepository r=mock(SubscriptionRepository.class);var free=new SubscriptionService.Subscription(1,"FREE","ACTIVE",true,Instant.now(),null);when(r.createFree("u@test")).thenReturn(free);assertThat(new SubscriptionService(r).current("u@test")).isSameAs(free);}@Test void refusesToCancelFreePlan(){SubscriptionRepository r=mock(SubscriptionRepository.class);when(r.current("u@test")).thenReturn(new SubscriptionService.Subscription(1,"FREE","ACTIVE",true,Instant.now(),null));assertThatThrownBy(()->new SubscriptionService(r).cancel("u@test")).isInstanceOf(ValidationException.class);verify(r,never()).cancelCurrent(anyString());}}
